package com.medtrack.transfer.controller; import com.medtrack.transfer.dto.*; import com.medtrack.transfer.service.TransferService; import jakarta.validation.Valid; import java.util.*; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/stock-transfers") public class TransferController {private final TransferService service;public TransferController(TransferService s){service=s;}@PostMapping@PreAuthorize("hasRole('SUPER_ADMIN') or hasRole('STORE_MANAGER') or hasRole('CENTRAL_WAREHOUSE_MANAGER')")public TransferResponse create(@AuthenticationPrincipal String user,@Valid @RequestBody TransferRequest r){return service.create(UUID.fromString(user),r);}@PostMapping("/{id}/approve")@PreAuthorize("hasRole('SUPER_ADMIN') or hasRole('CENTRAL_WAREHOUSE_MANAGER')")public TransferResponse approve(@AuthenticationPrincipal String user,@PathVariable UUID id){return service.approve(UUID.fromString(user),id);}@PostMapping("/{id}/allocate")@PreAuthorize("hasRole('SUPER_ADMIN') or hasRole('CENTRAL_WAREHOUSE_MANAGER')")public TransferResponse allocate(@AuthenticationPrincipal String user,@PathVariable UUID id){return service.allocate(UUID.fromString(user),id);}@PostMapping("/{id}/pick")@PreAuthorize("hasRole('SUPER_ADMIN') or hasRole('CENTRAL_WAREHOUSE_MANAGER')")public TransferResponse pick(@AuthenticationPrincipal String user,@PathVariable UUID id,@Valid @RequestBody PickRequest r){return service.pick(UUID.fromString(user),id,r);}@PostMapping("/{id}/pack")@PreAuthorize("hasRole('SUPER_ADMIN') or hasRole('CENTRAL_WAREHOUSE_MANAGER')")public TransferResponse pack(@PathVariable UUID id){return service.pack(id);}}
